# =============================================================================
# 2. RNG + helpers
# =============================================================================
def rng_for(seed: int, component: str) -> np.random.Generator:
    """Independent, named, seeded stream per component (stable if others change)."""
    return np.random.default_rng([seed, zlib.crc32(component.encode())])


def largest_remainder(total: int, weights: dict[str, float]) -> dict[str, int]:
    """Deterministic integer allocation whose counts sum exactly to `total`."""
    keys = list(weights)
    w = np.array([weights[k] for k in keys], dtype=float)
    p = w / w.sum()
    raw = p * total
    base = np.floor(raw).astype(int)
    rem = total - base.sum()
    order = sorted(range(len(keys)), key=lambda i: (-(raw[i] - base[i]), i))
    for i in order[:rem]:
        base[i] += 1
    return {k: int(c) for k, c in zip(keys, base)}


def uniform_stats(lo: float, hi: float) -> tuple[float, float]:
    return (lo + hi) / 2.0, (hi - lo) / math.sqrt(12.0)


def sha256_of(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def sigmoid(x: np.ndarray) -> np.ndarray:
    return 1.0 / (1.0 + np.exp(-x))


# =============================================================================
# 3. CONFIG VALIDATION
# =============================================================================
def validate_config(cfg: dict) -> None:
    assert cfg["total_records"] > 0, "total_records must be > 0"
    assert 0 < cfg["attack_ratio"] < 1, "attack_ratio must be in (0,1)"
    assert 0 < cfg["oversight_rate"] < 1, "oversight_rate must be in (0,1)"
    assert cfg["duration_hours"] > 0, "duration_hours must be > 0"
    assert cfg["score_mode"] in ("evidence", "legacy_risk")
    dw = cfg["device_weights"]
    assert set(dw) == set(cfg["devices"]), "device_weights keys must match devices"
    assert abs(sum(dw.values()) - 1.0) < 1e-9, "device_weights must sum to 1"
    for key in ("benign_probabilities", "attack_probabilities"):
        assert abs(sum(cfg["destination_categories"][key].values()) - 1) < 1e-9, f"{key} must sum to 1"
    pw = sum(p["weight"] for p in cfg["profiles"].values())
    assert abs(pw - 1.0) < 1e-9, "profile weights must sum to 1"
    aux = sum(s["probability"] for s in cfg["benign_auxiliary_services"].values())
    assert 0 <= aux < 1
    s = cfg["splits"]
    assert abs(s["train"] + s["validation"] + s["test"] - 1) < 1e-9
    for a, c in cfg["attacks"].items():
        assert 0 <= c["uses_normal_ports"] <= 1 and 0 <= c["data_similarity"] <= 1, a
        assert c["weight"] > 0, a


# =============================================================================
# 4. GENERATOR
# =============================================================================
class HITLIoTGeneratorV11:
    """Generate the HITL-IoT v1.1 benchmark from a validated configuration."""

    def __init__(self, cfg: dict):
        validate_config(cfg)
        self.cfg = cfg
        self.seed = int(cfg["seed"])
        self.device_names = list(cfg["devices"])
        self.attack_names = list(cfg["attacks"])
        w = np.array([cfg["attacks"][a]["weight"] for a in self.attack_names])
        self.attack_proportions = dict(zip(self.attack_names, (w / w.sum()).tolist()))
        # configured benign baselines (from config, never from labelled data)
        self.baselines = {}
        for d, c in cfg["devices"].items():
            self.baselines[d] = {
                "bytes_sent": uniform_stats(*c["bytes_sent_range"]),
                "duration": uniform_stats(*c["duration_range_s"]),
                "packet_size": uniform_stats(*c["packet_size_range"]),
            }

    # ---------------- counts ----------------
    def counts(self) -> tuple[int, int, int]:
        n = self.cfg["total_records"]
        n_att = int(round(n * self.cfg["attack_ratio"]))
        n_ben = n - n_att
        assert n_att + n_ben == n
        return n, n_ben, n_att

    # ---------------- 5-6. flow generation ----------------
    def _generate_flows(self) -> pd.DataFrame:
        cfg, seed = self.cfg, self.seed
        n, n_ben, n_att = self.counts()
        is_attack = np.r_[np.zeros(n_ben, bool), np.ones(n_att, bool)]

        # attack types: deterministic largest-remainder counts, seeded shuffle
        att_counts = largest_remainder(n_att, self.attack_proportions)
        att_types = np.concatenate([[a] * c for a, c in att_counts.items()]).astype(object)
        rng_for(seed, "attack_assignment").shuffle(att_types)
        attack_type = np.r_[np.full(n_ben, "normal", dtype=object), att_types]

        # devices: explicit allocation within each class, seeded shuffle
        dev = np.empty(n, dtype=object)
        for cls, (start, size) in {"benign": (0, n_ben), "attack": (n_ben, n_att)}.items():
            dc = largest_remainder(size, cfg["device_weights"])
            arr = np.concatenate([[d] * c for d, c in dc.items()]).astype(object)
            rng_for(seed, f"device_assignment_{cls}").shuffle(arr)
            dev[start:start + size] = arr

        r = rng_for(seed, "flows")
        instance = np.empty(n, dtype=int)
        for d in self.device_names:
            m = dev == d
            instance[m] = r.choice(cfg["devices"][d]["instances"], size=m.sum())

        ts_sec = r.integers(0, cfg["duration_hours"] * 3600, size=n)

        dst_port = np.zeros(n, int)
        bytes_sent = np.zeros(n, float)
        duration = np.zeros(n, float)
        pkt_size = np.zeros(n, float)
        udp443 = np.zeros(n, float)

        # ---- benign ----
        ben_idx = np.where(~is_attack)[0]
        u = r.random(ben_idx.size)
        aux = cfg["benign_auxiliary_services"]
        edges, names = [], []
        acc = 0.0
        for name, s in aux.items():
            acc += s["probability"]
            edges.append(acc)
            names.append(name)
        svc = np.full(ben_idx.size, "device", dtype=object)
        prev = 0.0
        for name, e in zip(names, edges):
            svc[(u >= prev) & (u < e)] = name
            prev = e
        for name in names:
            m = ben_idx[svc == name]
            s = aux[name]
            dst_port[m] = s["port"]
            bytes_sent[m] = r.integers(s["bytes_sent_range"][0], s["bytes_sent_range"][1] + 1, m.size)
            duration[m] = r.uniform(*s["duration_range_s"], m.size)
            pkt_size[m] = r.integers(s["packet_size_range"][0], s["packet_size_range"][1] + 1, m.size)
        for d in self.device_names:
            c = cfg["devices"][d]
            m = ben_idx[(svc == "device") & (dev[ben_idx] == d)]
            dst_port[m] = r.choice(c["normal_ports"], size=m.size)
            bytes_sent[m] = r.integers(c["bytes_sent_range"][0], c["bytes_sent_range"][1] + 1, m.size)
            duration[m] = r.uniform(*c["duration_range_s"], m.size)
            pkt_size[m] = r.integers(c["packet_size_range"][0], c["packet_size_range"][1] + 1, m.size)
            udp443[m] = c["udp_443_probability"]
        lo, hi = cfg["benign_bytes_received_factor"]
        bytes_received = np.zeros(n, float)
        bytes_received[ben_idx] = np.floor(bytes_sent[ben_idx] * r.uniform(lo, hi, ben_idx.size))

        # ---- attacks ----
        for a in self.attack_names:
            ac = cfg["attacks"][a]
            for d in self.device_names:
                m = np.where(is_attack & (attack_type == a) & (dev == d))[0]
                if m.size == 0:
                    continue
                dc = cfg["devices"][d]
                mimic = r.random(m.size) < ac["uses_normal_ports"]
                ports = r.choice(ac["service_ports"], size=m.size)
                if ac["random_port_probability"] > 0:
                    rp = r.random(m.size) < ac["random_port_probability"]
                    ports[rp] = r.integers(1, 65536, rp.sum())
                ports[mimic] = r.choice(dc["normal_ports"], size=mimic.sum())
                dst_port[m] = ports
                # Eq. 1a-1c byte bands
                sim = ac["data_similarity"]
                band = next(b for b in cfg["similarity_bands"] if sim > b["min_exclusive"])
                bmin, bmax = dc["bytes_sent_range"]
                f0, f1 = band["bytes_factor"]
                bytes_sent[m] = r.integers(int(bmin * f0), int(bmax * f1) + 1, m.size)
                # duration / packet size: benign-like with probability delta_a
                like = r.random(m.size) < sim
                duration[m] = np.where(like, r.uniform(*dc["duration_range_s"], m.size),
                                       r.uniform(*ac["duration_range_s"], m.size))
                like2 = r.random(m.size) < sim
                pkt_size[m] = np.where(
                    like2, r.integers(dc["packet_size_range"][0], dc["packet_size_range"][1] + 1, m.size),
                    r.integers(ac["packet_size_range"][0], ac["packet_size_range"][1] + 1, m.size))
                udp443[m] = cfg["attack_udp_443_probability"]
        att_idx = np.where(is_attack)[0]
        lo, hi = cfg["attack_bytes_received_factor"]
        bytes_received[att_idx] = np.floor(bytes_sent[att_idx] * r.uniform(lo, hi, att_idx.size))

        # ---- transport protocol (port-derived; UDP/443 = QUIC-like) ----
        udp = np.isin(dst_port, cfg["udp_ports"]) | ((dst_port == 443) & (r.random(n) < udp443))
        protocol = np.where(udp, "UDP", "TCP")

        # ---- destination category + documentation-block address ----
        dcfg = cfg["destination_categories"]
        cats = list(dcfg["benign_probabilities"])
        dst_cat = np.empty(n, dtype=object)
        dst_cat[~is_attack] = r.choice(cats, size=n_ben, p=[dcfg["benign_probabilities"][c] for c in cats])
        dst_cat[is_attack] = r.choice(cats, size=n_att, p=[dcfg["attack_probabilities"][c] for c in cats])
        host = r.integers(1, dcfg["hosts_per_pool"] + 1, n)
        dst_ip = np.array([dcfg["address_pools"][c] + str(h) for c, h in zip(dst_cat, host)], dtype=object)
        src_port = r.integers(49152, 65536, n)

        return pd.DataFrame({
            "_gen_index": np.arange(n), "_ts_sec": ts_sec, "device_type": dev, "_instance": instance,
            "is_attack": is_attack, "attack_type": attack_type, "dst_port": dst_port,
            "src_port": src_port, "protocol": protocol, "dst_category": dst_cat, "dst_ip": dst_ip,
            "bytes_sent": bytes_sent.astype(np.int64), "bytes_received": bytes_received.astype(np.int64),
            "duration": duration, "packet_size": pkt_size.astype(np.int64),
        })

    # ---------------- 7. derived features ----------------
    def _derive_features(self, df: pd.DataFrame) -> pd.DataFrame:
        cfg = self.cfg
        df = df.sort_values(["_ts_sec", "_gen_index"], kind="mergesort").reset_index(drop=True)
        df.insert(0, "flow_id", [f"HITL11-{i + 1:06d}" for i in range(len(df))])
        start = datetime.fromisoformat(cfg["start_time"])
        ts = pd.to_datetime(start) + pd.to_timedelta(df["_ts_sec"], unit="s")
        df.insert(1, "timestamp", ts.dt.strftime("%Y-%m-%dT%H:%M:%S"))
        df["hour"] = ts.dt.hour
        df["day_of_week"] = ts.dt.weekday
        df["is_weekend"] = df["day_of_week"] >= 5
        df["is_business_hours"] = (df["hour"] >= 9) & (df["hour"] <= 17)
        df["is_night"] = (df["hour"] >= 22) | (df["hour"] <= 6)

        df["src_ip"] = cfg["lan_prefix"] + df["_instance"].astype(str)
        df["src_mac"] = "00:1A:2B:3C:4D:" + df["_instance"].astype(str).str.zfill(2)
        df["dst_mac"] = cfg["gateway_mac"]  # external flows traverse the gateway
        df["device_name"] = df["device_type"] + "_" + df["_instance"].astype(str)
        for d in self.device_names:
            df[f"device_{d}"] = df["device_type"] == d
        df["ttl"] = df["device_type"].map({d: c["initial_ttl"] for d, c in cfg["devices"].items()})

        df["service_category"] = df["dst_port"].map(SERVICE_MAP).fillna("other")
        df["is_well_known_port"] = df["dst_port"] <= 1023
        df["is_registered_port"] = (df["dst_port"] >= 1024) & (df["dst_port"] <= 49151)
        df["is_dynamic_port"] = df["dst_port"] >= 49152
        aux_ports = [s["port"] for s in cfg["benign_auxiliary_services"].values()]
        expected = np.zeros(len(df), bool)
        for d, c in cfg["devices"].items():
            m = (df["device_type"] == d).to_numpy()
            expected[m] = df.loc[m, "dst_port"].isin(c["normal_ports"] + aux_ports).to_numpy()
        df["port_expected_for_device"] = expected

        tot = df["bytes_sent"] + df["bytes_received"]
        df["packet_count"] = np.maximum(1, np.ceil(tot / df["packet_size"])).astype(np.int64)
        df["bytes_ratio"] = df["bytes_sent"] / np.maximum(df["bytes_received"], 1)
        df["bytes_per_second"] = tot / np.maximum(df["duration"], 0.01)
        df["packet_rate"] = df["packet_count"] / np.maximum(df["duration"], 0.01)

        # device-baseline deviations  delta_i = |f_i - mu_d| / sigma_d  (configured benign ranges)
        for feat, col in (("bytes_sent", "baseline_deviation"), ("duration", "duration_deviation"),
                          ("packet_size", "packet_size_deviation")):
            mu = df["device_type"].map({d: self.baselines[d][feat][0] for d in self.device_names})
            sd = df["device_type"].map({d: self.baselines[d][feat][1] for d in self.device_names})
            df[col] = (df[feat] - mu).abs() / sd.where(sd > 0, 1.0)
        return df

    # ---------------- 8. historical features (no current/future leakage) ----------------
    def _historical_features(self, df: pd.DataFrame) -> pd.DataFrame:
        """Prior-only historical features.

        * df is already sorted chronologically by (timestamp, generation index) = flow_id order.
        * shift(1) excludes the current flow; windows are trailing (never centred, no negative
          shift, no forward-looking window), so no later flow contributes to an earlier row.
        * Computed once over the full timeline BEFORE any split: a validation/test row may use
          history from earlier (training-period) flows, which is past information and therefore
          not leakage; no training row ever uses information from a later period.
        """
        cfg = self.cfg
        mu = df["device_type"].map({d: self.baselines[d]["bytes_sent"][0] for d in self.device_names})
        sd = df["device_type"].map({d: self.baselines[d]["bytes_sent"][1] for d in self.device_names})
        g = df.groupby("device_name", sort=False)["bytes_sent"]
        prev = g.shift(1)  # exclude the current flow
        for w in cfg["rolling_windows"]:
            grp = prev.groupby(df["device_name"], sort=False)
            m = grp.rolling(w, min_periods=1).mean().reset_index(level=0, drop=True)
            s = grp.rolling(w, min_periods=2).std().reset_index(level=0, drop=True)
            df[f"bytes_sent_mean_{w}"] = m.sort_index().fillna(mu)
            df[f"bytes_sent_std_{w}"] = s.sort_index().fillna(sd)
        for col, win in cfg["connection_windows_s"].items():
            out = np.zeros(len(df), dtype=np.int64)
            for _, idx in df.groupby("device_name", sort=False).indices.items():
                t = df["_ts_sec"].to_numpy()[idx]  # already sorted by (ts, gen_index)
                left = np.searchsorted(t, t - win, side="left")
                out[idx] = np.arange(idx.size) - left
            df[col] = out
        return df

    # ---------------- 9-10. evidence, construction score, ambiguity ----------------
    def _evidence(self, df: pd.DataFrame) -> dict[str, np.ndarray]:
        ev = self.cfg["evidence"]
        sc = ev["deviation_scale"]
        aux_ports = [s["port"] for s in self.cfg["benign_auxiliary_services"].values()]
        e_port = np.where(df["port_expected_for_device"], 0.0, 1.0)
        e_port = np.where(df["dst_port"].isin(aux_ports), ev["auxiliary_port_evidence"], e_port)
        comps = {
            "bytes": np.tanh(df["baseline_deviation"].to_numpy() / sc),
            "duration": np.tanh(df["duration_deviation"].to_numpy() / sc),
            "port": e_port,
            "ratio": np.tanh(np.abs(np.log(np.maximum(df["bytes_ratio"].to_numpy(), 1e-6))) / ev["ratio_scale"]),
            "packet_size": np.tanh(df["packet_size_deviation"].to_numpy() / sc),
        }
        fw = ev["flow_weights"]
        flow = sum(fw[k] * comps[k] for k in fw) / sum(fw.values())
        dst = df["dst_category"].map(ev["destination_category_evidence"]).to_numpy(float)
        dns = ((df["dst_port"] == 53) & (df["bytes_sent"] > ev["dns_payload_bytes_threshold"])).to_numpy(float)
        comps.update({"flow": flow, "destination": dst, "dns_payload": dns,
                      "context": np.maximum(dst, dns)})
        return comps

    def _construction_score(self, df: pd.DataFrame, E: dict) -> pd.DataFrame:
        cfg = self.cfg
        r = rng_for(self.seed, "construction_score")
        if cfg["score_mode"] == "evidence":
            cs = cfg["construction_score"]
            z = cs["slope"] * (E["flow"] - cs["offset"]) + r.normal(0, cs["logit_noise_sd"], len(df))
            score = sigmoid(z)
            thr = cfg["decision_threshold"]
        else:  # legacy_risk (v1.0 behaviour; label-conditioned)
            lr = cfg["legacy_risk"]
            risk = np.zeros(len(df))
            b = ~df["is_attack"].to_numpy()
            risk[b] = r.uniform(*lr["benign_risk_range"], b.sum())
            for a in self.attack_names:
                m = (df["attack_type"] == a).to_numpy()
                risk[m] = r.uniform(*cfg["attacks"][a]["legacy_risk_range"], m.sum())
            df["configured_intrinsic_risk"] = risk
            h = lr["noise_half_width"]
            score = np.clip(risk + r.uniform(-h, h, len(df)), 0, 1)
            thr = lr["decision_threshold"]
        df["generated_attack_score"] = score
        df["generated_prediction"] = (score > thr).astype(np.int64)
        df["ambiguity_score"] = 1.0 - 2.0 * np.abs(score - 0.5)
        return df

    # ---------------- 11. deterministic Top-K ----------------
    def _select_top_k(self, df: pd.DataFrame) -> np.ndarray:
        k = int(math.floor(self.cfg["oversight_rate"] * len(df)))
        order = np.lexsort((np.arange(len(df)), -df["ambiguity_score"].to_numpy()))
        sel = np.zeros(len(df), bool)
        sel[order[:k]] = True
        return sel

    # ---------------- 12-13. oversight metadata + rationale ----------------
    def _oversight(self, df: pd.DataFrame, E: dict) -> pd.DataFrame:
        cfg = self.cfg
        sel = self._select_top_k(df)
        df["oversight_selected"] = sel
        idx = np.where(sel)[0]  # ascending flow order -> deterministic
        r = rng_for(self.seed, "oversight")
        profs = list(cfg["profiles"])
        assigned = r.choice(profs, size=idx.size, p=[cfg["profiles"][p]["weight"] for p in profs])

        dec = np.full(len(df), np.nan)
        conf = np.full(len(df), np.nan)
        lat = np.full(len(df), np.nan)
        prof_col = np.full(len(df), None, dtype=object)
        prof_col[idx] = assigned
        amb = df["ambiguity_score"].to_numpy()
        score = df["generated_attack_score"].to_numpy()
        pred = df["generated_prediction"].to_numpy()
        y = df["is_attack"].to_numpy().astype(int)
        cm = cfg["confidence_model"]
        # Anchoring uses the evidence-scale value implied by the construction score
        # (inverse of sigmoid(slope*(E - offset))). v1.1-draft added the raw score
        # (centred at 0.5) to evidence thresholded at 0.35 - a unit mismatch that
        # biased every anchored profile towards "attack".
        cs = cfg["construction_score"]
        sc = np.clip(score, 1e-9, 1 - 1e-9)
        implied = cs["offset"] + np.log(sc / (1 - sc)) / cs["slope"]
        margin_all = np.full(len(df), np.nan)

        for p in profs:
            pc = cfg["profiles"][p]
            ii = idx[assigned == p]
            if ii.size == 0:
                continue
            clo, chi = pc["confidence_range"]
            if cfg["legacy_profile_mode"]:
                correct = r.random(ii.size) < pc["legacy_accuracy"]
                d = np.where(correct, y[ii], 1 - y[ii])
                agree = d == pred[ii]
                c = np.where(agree, r.uniform(clo, chi, ii.size), r.uniform(clo * 0.7, chi * 0.85, ii.size))
            else:
                wc, wa = pc["context_weight"], pc["anchor_weight"]
                P = wa * implied[ii] + (1 - wa) * ((1 - wc) * E["flow"][ii] + wc * E["context"][ii])
                noisy = P + r.normal(0, pc["noise_sd"], ii.size)
                margin = noisy - pc["threshold"]
                d = (margin > 0).astype(int)
                strength = np.tanh(np.abs(margin) / cm["margin_scale"]) * (1 - cm["ambiguity_penalty"] * amb[ii])
                c = clo + (chi - clo) * strength + r.normal(0, cm["noise_sd"], ii.size)
                margin_all[ii] = margin
            dec[ii] = d
            conf[ii] = np.clip(c, 0, 1)
            tlo, thi = pc["latency_range_s"]
            lat[ii] = r.uniform(tlo, thi, ii.size) * (1 + cfg["latency_model"]["ambiguity_coefficient"] * amb[ii])

        df["oversight_profile"] = prof_col
        df["profile_decision"] = pd.array(np.where(np.isnan(dec), pd.NA, dec), dtype="Int64")
        df["profile_confidence"] = conf
        df["generated_decision_latency"] = lat
        agree = pd.array([pd.NA] * len(df), dtype="boolean")
        agree[idx] = dec[idx].astype(int) == pred[idx]
        df["model_profile_agreement"] = agree
        df["profile_rationale"] = self._rationales(df, E, idx, dec, prof_col)
        return df

    def _rationales(self, df, E, idx, dec, prof_col) -> np.ndarray:
        rc = self.cfg["rationale"]
        out = np.full(len(df), None, dtype=object)
        phrases = {
            "bytes": "byte volume deviates from the device baseline",
            "duration": "flow duration is atypical for the device type",
            "port": "destination port is outside the device's expected service set",
            "packet_size": "packet-size profile is atypical for the device type",
            "ratio": "transfer direction is strongly asymmetric",
        }
        amb = df["ambiguity_score"].to_numpy()
        for i in idx:
            pc = self.cfg["profiles"][prof_col[i]]
            flags = []
            for k in ("bytes", "duration", "port", "packet_size"):
                if E[k][i] >= rc["deviation_flag"]:
                    flags.append((E[k][i], phrases[k]))
            if E["ratio"][i] >= rc["ratio_flag"]:
                flags.append((E["ratio"][i], phrases["ratio"]))
            if pc["context_weight"] >= rc["context_visibility_min_weight"] or self.cfg["legacy_profile_mode"]:
                if E["dns_payload"][i] > 0:
                    flags.append((1.0, "DNS-port flow carries an unusually large payload"))
                cat = df.at[i, "dst_category"]
                if cat != "legitimate_like":
                    flags.append((E["destination"][i], f"destination is in the {cat.replace('_', '-')} category"))
            flags.sort(key=lambda t: (-t[0], t[1]))
            reasons = [f[1] for f in flags[: rc["max_reasons"]]]
            if int(dec[i]) == 1:
                body = "; ".join(reasons) if reasons else "combined weak indicators exceed the profile threshold"
                txt = f"Assessed as attack: {body}"
            else:
                txt = "Assessed as benign: flow features are close to the device baseline"
                if reasons:
                    txt += f" despite: {reasons[0]}"
            if amb[i] >= rc["high_ambiguity"]:
                txt += " (high ambiguity of the generated score)"
            out[i] = txt + "."
        return out

    # ---------------- run ----------------
    def generate(self, verbose: bool = True) -> pd.DataFrame:
        log = print if verbose else (lambda *a, **k: None)
        n, nb, na = self.counts()
        log(f"Generating {n:,} flows ({nb:,} benign / {na:,} attack), seed={self.seed}, "
            f"score_mode={self.cfg['score_mode']}, legacy_profile_mode={self.cfg['legacy_profile_mode']}")
        df = self._generate_flows()
        log("Deriving flow features ...")
        df = self._derive_features(df)
        log("Computing historical (prior-only) features ...")
        df = self._historical_features(df)
        E = self._evidence(df)
        log("Computing construction score and ambiguity ...")
        df = self._construction_score(df, E)
        log("Selecting Top-K oversight subset and generating profile metadata ...")
        df = self._oversight(df, E)
        return self._order_columns(df.drop(columns=["_gen_index", "_ts_sec", "_instance"]))

    def _order_columns(self, df: pd.DataFrame) -> pd.DataFrame:
        order = [c for c in COLUMN_ORDER if c in df.columns]
        extra = [c for c in df.columns if c not in order]
        return df[order + extra]


# =============================================================================
# 14-17. SCHEMA, FEATURE POLICY, STATISTICS
# =============================================================================
# name: (dtype, category, units, definition, track1, track2)
S = "identifier"; F = "generated_flow_evidence"; C = "contextual_feature"; H = "historical_feature"
L = "target_label"; B = "benchmark_construction_variable"; O = "generated_oversight_metadata"
SCHEMA: dict[str, tuple] = {
    "flow_id": ("string", S, "", "Stable unique flow identifier (sorted by timestamp, generation index)", False, False),
    "timestamp": ("string", S, "ISO-8601", "Generated flow start time", False, False),
    "hour": ("int", C, "hour", "Hour of day of timestamp", True, True),
    "day_of_week": ("int", C, "0=Mon", "Weekday of timestamp", True, True),
    "is_weekend": ("bool", C, "", "day_of_week >= 5", True, True),
    "is_business_hours": ("bool", C, "", "9 <= hour <= 17", True, True),
    "is_night": ("bool", C, "", "hour >= 22 or hour <= 6", True, True),
    "src_ip": ("string", S, "", "Private LAN address of the device instance", False, False),
    "dst_ip": ("string", S, "", "RFC 5737 documentation address; pool encodes dst_category; no live reputation claim", False, False),
    "src_mac": ("string", S, "", "Device instance MAC", False, False),
    "dst_mac": ("string", S, "", "Gateway MAC (constant for external flows)", False, False),
    "dst_category": ("string", C, "", "Configured destination category (legitimate_like/ambiguous/suspicious_like); threat-intelligence-like context", True, True),
    "protocol": ("string", F, "", "Transport protocol (TCP/UDP), derived from port rules", True, True),
    "src_port": ("int", S, "", "Ephemeral source port (uninformative by design)", False, False),
    "dst_port": ("int", F, "", "Destination port", True, True),
    "service_category": ("string", F, "", "Port-derived service category (not an application-layer emulation)", True, True),
    "is_well_known_port": ("bool", F, "", "dst_port <= 1023", True, True),
    "is_registered_port": ("bool", F, "", "1024 <= dst_port <= 49151", True, True),
    "is_dynamic_port": ("bool", F, "", "dst_port >= 49152", True, True),
    "port_expected_for_device": ("bool", F, "", "dst_port in device normal ports or benign auxiliary ports (DNS/NTP)", True, True),
    "device_name": ("string", S, "", "Device instance identifier", False, False),
    "device_type": ("string", C, "", "One of thermostat, camera, speaker, tv, doorbell", True, True),
    "device_thermostat": ("bool", C, "", "One-hot device type", True, True),
    "device_camera": ("bool", C, "", "One-hot device type", True, True),
    "device_speaker": ("bool", C, "", "One-hot device type", True, True),
    "device_tv": ("bool", C, "", "One-hot device type", True, True),
    "device_doorbell": ("bool", C, "", "One-hot device type", True, True),
    "ttl": ("int", F, "hops", "Device-specific initial IP TTL observed at the gateway", True, True),
    "packet_size": ("int", F, "bytes", "Mean packet size of the flow", True, True),
    "packet_count": ("int", F, "packets", "ceil((bytes_sent+bytes_received)/packet_size), >= 1", True, True),
    "duration": ("float", F, "s", "Flow duration", True, True),
    "bytes_sent": ("int", F, "bytes", "Bytes from device to destination", True, True),
    "bytes_received": ("int", F, "bytes", "Bytes from destination to device", True, True),
    "bytes_ratio": ("float", F, "", "bytes_sent / max(bytes_received,1)", True, True),
    "bytes_per_second": ("float", F, "bytes/s", "(bytes_sent+bytes_received)/max(duration,0.01)", True, True),
    "packet_rate": ("float", F, "packets/s", "packet_count/max(duration,0.01)", True, True),
    "baseline_deviation": ("float", F, "sigma", "|bytes_sent - mu_d| / sigma_d using configured benign device range (uniform)", True, True),
    "duration_deviation": ("float", F, "sigma", "|duration - mu_d| / sigma_d (configured benign range)", True, True),
    "packet_size_deviation": ("float", F, "sigma", "|packet_size - mu_d| / sigma_d (configured benign range)", True, True),
    "connection_frequency": ("int", H, "flows/min", "Prior flows from same device instance in preceding 60 s (current excluded)", True, True),
    "connection_count_prev_5min": ("int", H, "flows", "Prior flows from same instance in preceding 300 s", True, True),
    "connection_count_prev_10min": ("int", H, "flows", "Prior flows from same instance in preceding 600 s", True, True),
    **{f"bytes_sent_{s}_{w}": ("float", H, "bytes",
                               f"Rolling {s} of bytes_sent over previous {w} flows of same instance (current excluded; "
                               f"first flows filled with configured device baseline {'mean' if s == 'mean' else 'std'})", True, True)
       for w in (5, 10, 20) for s in ("mean", "std")},
    "is_attack": ("bool", L, "", "Ground-truth binary label (evaluation/target only)", False, False),
    "attack_type": ("string", L, "", "Ground-truth category: normal or one of 12 attack categories", False, False),
    "configured_intrinsic_risk": ("float", B, "[0,1]", "LEGACY MODE ONLY: label-conditioned risk (v1.0 risk_score)", False, False),
    "generated_attack_score": ("float", B, "[0,1]", "Construction score: sigmoid(slope*(flow_evidence - offset) + N(0,sd)); NOT a trained-classifier probability", False, True),
    "generated_prediction": ("int", B, "{0,1}", "generated_attack_score > decision_threshold", False, True),
    "ambiguity_score": ("float", B, "[0,1]", "1 - 2|generated_attack_score - 0.5|", False, True),
    "oversight_selected": ("bool", O, "", "True for the Top-K ambiguity flows", False, True),
    "oversight_profile": ("string", O, "", "Configured oversight profile (high/medium/low_competence); NOT a real analyst", False, True),
    "profile_decision": ("Int64", O, "{0,1}", "Generated profile decision (null if not selected)", False, True),
    "profile_confidence": ("float", O, "[0,1]", "Generated profile confidence; independent of ground truth and of model agreement", False, True),
    "generated_decision_latency": ("float", O, "s", "Generated latency: U(profile range)*(1+0.5*ambiguity); NOT a measured response time", False, True),
    "model_profile_agreement": ("boolean", O, "", "profile_decision == generated_prediction (task target for disagreement prediction)", False, False),
    "profile_rationale": ("string", O, "", "Template-generated benchmark rationale; NOT analyst reasoning", False, True),
}
COLUMN_ORDER = list(SCHEMA)
TRACK1_FLOW_ONLY_EXCLUDE = {"dst_category"}


def schema_frame(df: pd.DataFrame) -> pd.DataFrame:
    rows = []
    for col in df.columns:
        dtype, cat, units, desc, t1, t2 = SCHEMA[col]
        s = df[col]
        if pd.api.types.is_numeric_dtype(s) and not pd.api.types.is_bool_dtype(s):
            rng = f"[{s.min():.6g}, {s.max():.6g}]"
        elif s.nunique(dropna=True) <= 20:
            rng = "{" + ", ".join(map(str, sorted(s.dropna().unique(), key=str))) + "}"
        else:
            rng = f"{s.nunique(dropna=True)} distinct values"
        rows.append({"field": col, "dtype": dtype, "category": cat, "units": units, "definition": desc,
                     "observed_range": rng, "track1_allowed": t1, "track2_allowed": t2,
                     "nullable": bool(s.isna().any()),
                     "provenance": "generated (simulation)" if cat != L else "generated ground-truth label"})
    return pd.DataFrame(rows)


def feature_policy(df: pd.DataFrame) -> dict:
    cols = list(df.columns)
    t1 = [c for c in cols if SCHEMA[c][4]]
    t2 = [c for c in cols if SCHEMA[c][5]]
    return {
        "version": GENERATOR_VERSION,
        "column_categories": {c: SCHEMA[c][1] for c in cols},
        "track1_primary_flow_only": [c for c in t1 if c not in TRACK1_FLOW_ONLY_EXCLUDE],
        "track1_context_enriched": t1,
        "track2_oversight": t2,
        "roles": {"track1_primary_flow_only": "PRIMARY IDS feature set (transferable flow/device/temporal/"
                                              "behavioural/historical evidence; eases alignment with CICIoT2023/ToN-IoT)",
                  "track1_context_enriched": "SECONDARY contextual experiment (adds dst_category)",
                  "track2_oversight": "oversight-mechanism tasks"},
        "evaluation_targets": ["is_attack", "attack_type", "model_profile_agreement"],
        "notes": [
            "Track 1 (IDS) must never use labels, construction variables, or oversight metadata.",
            "dst_category is synthetic threat-intelligence-like context and is excluded from the primary "
            "Track-1 set; use track1_context_enriched only as a secondary experiment.",
            "model_profile_agreement is a target for disagreement prediction, never an input.",
            "Track 2 uses the generated construction score only as a benchmark signal; "
            "genuine ML-uncertainty experiments should use trained-model held-out probabilities.",
        ],
    }


def temporal_split(df: pd.DataFrame, cfg: dict) -> np.ndarray:
    """PRIMARY: chronological 70/15/15 by (timestamp, flow_id). Cut points are moved forward to
    the next timestamp change so boundaries are strict (max(train) < min(val) < ... )."""
    s = cfg["splits"]
    order = np.lexsort((df["flow_id"].to_numpy(), df["timestamp"].to_numpy()))
    ts = df["timestamp"].to_numpy()[order]
    n = len(df)

    def cut(k: int) -> int:
        while 0 < k < n and ts[k] == ts[k - 1]:
            k += 1
        return k
    c1 = cut(int(round(s["train"] * n)))
    c2 = cut(int(round((s["train"] + s["validation"]) * n)))
    lab = np.empty(n, dtype=object)
    lab[order[:c1]] = "train"
    lab[order[c1:c2]] = "validation"
    lab[order[c2:]] = "test"
    return lab


def make_splits(df: pd.DataFrame, cfg: dict) -> pd.DataFrame:
    """Split file: flow_id, timestamp, temporal_split (PRIMARY), iid_split (SECONDARY)."""
    s = cfg["splits"]
    r = rng_for(cfg["seed"], "splits")
    split = np.empty(len(df), dtype=object)
    for _, idx in df.groupby(s["stratify_by"], sort=True).indices.items():
        idx = np.array(sorted(idx))
        r.shuffle(idx)
        n_tr = int(round(s["train"] * idx.size))
        n_va = int(round(s["validation"] * idx.size))
        split[idx[:n_tr]] = "train"
        split[idx[n_tr:n_tr + n_va]] = "validation"
        split[idx[n_tr + n_va:]] = "test"
    return pd.DataFrame({"flow_id": df["flow_id"], "timestamp": df["timestamp"],
                         "temporal_split": temporal_split(df, cfg), "iid_split": split})


def split_summary(df: pd.DataFrame, sp: pd.DataFrame) -> dict:
    out = {}
    for col, name in (("temporal_split", "temporal"), ("iid_split", "iid_stratified")):
        d = {}
        for part in ("train", "validation", "test"):
            m = (sp[col] == part).to_numpy()
            sub = df[m]
            d[part] = {"count": int(m.sum()), "proportion": round(float(m.mean()), 5),
                       "attack_count": int(sub["is_attack"].sum()),
                       "attack_rate": round(float(sub["is_attack"].mean()), 5),
                       "first_timestamp": sub["timestamp"].min(), "last_timestamp": sub["timestamp"].max(),
                       "oversight_selected": int(sub["oversight_selected"].sum())}
        out[name] = d
    return out


def _auc(x: np.ndarray, y: np.ndarray) -> float:
    ranks = pd.Series(x).rank(method="average").to_numpy()
    n1 = y.sum(); n0 = y.size - n1
    return float((ranks[y == 1].sum() - n1 * (n1 + 1) / 2) / (n1 * n0))


def _ece(conf: np.ndarray, correct: np.ndarray, bins: int = 10) -> float:
    edges = np.linspace(0, 1, bins + 1); e = 0.0
    for i in range(bins):
        m = (conf > edges[i]) & (conf <= edges[i + 1])
        if m.any():
            e += m.mean() * abs(conf[m].mean() - correct[m].mean())
    return float(e)


def pct_table(s: pd.Series) -> dict:
    vc = s.value_counts()
    return {str(k): {"count": int(v), "percent": round(100 * v / len(s), 3)} for k, v in vc.items()}


def summarise(df: pd.DataFrame, gen: HITLIoTGeneratorV11) -> dict:
    cfg = gen.cfg
    y = df["is_attack"].to_numpy()
    att = df[df["is_attack"]]; ben = df[~df["is_attack"]]
    ov = df[df["oversight_selected"]]
    normal_ports = att["port_expected_for_device"]
    summ: dict[str, Any] = {
        "dataset": {"name": cfg["dataset_name"], "version": cfg["version"], "seed": cfg["seed"],
                    "rows": len(df), "columns": df.shape[1], "duration_hours": cfg["duration_hours"],
                    "first_timestamp": df["timestamp"].min(), "last_timestamp": df["timestamp"].max(),
                    "score_mode": cfg["score_mode"], "legacy_profile_mode": cfg["legacy_profile_mode"]},
        "class_distribution": pct_table(df["is_attack"].map({True: "attack", False: "benign"})),
        "device_distribution": pct_table(df["device_type"]),
        "device_instances": {d: int(df.loc[df.device_type == d, "device_name"].nunique()) for d in gen.device_names},
        "attack_distribution_observed": pct_table(att["attack_type"]),
        "attack_distribution_configured_percent": {a: round(100 * p, 3) for a, p in gen.attack_proportions.items()},
        "protocol_distribution": pct_table(df["protocol"]),
        "protocol_by_class": {k: pct_table(g["protocol"]) for k, g in (("benign", ben), ("attack", att))},
        "service_category_distribution": pct_table(df["service_category"]),
        "destination_category": {"benign": pct_table(ben["dst_category"]), "attack": pct_table(att["dst_category"])},
        "port_mimicry": {
            "configured_range_percent": [round(100 * min(a["uses_normal_ports"] for a in cfg["attacks"].values()), 1),
                                         round(100 * max(a["uses_normal_ports"] for a in cfg["attacks"].values()), 1)],
            "observed_attack_rate_device_expected_port_percent": round(100 * normal_ports.mean(), 3),
            "per_attack_percent": {a: round(100 * g["port_expected_for_device"].mean(), 2)
                                   for a, g in att.groupby("attack_type")},
        },
        "byte_volume": {
            "benign_median": float(ben["bytes_sent"].median()), "attack_median": float(att["bytes_sent"].median()),
            "median_byte_volume_ratio": round(min(ben["bytes_sent"].median(), att["bytes_sent"].median())
                                              / max(ben["bytes_sent"].median(), att["bytes_sent"].median()), 4),
            "benign_iqr": [float(ben["bytes_sent"].quantile(.25)), float(ben["bytes_sent"].quantile(.75))],
            "attack_iqr": [float(att["bytes_sent"].quantile(.25)), float(att["bytes_sent"].quantile(.75))],
            "wasserstein_log10_bytes": _wasserstein(np.log10(ben["bytes_sent"] + 1), np.log10(att["bytes_sent"] + 1)),
        },
        "core_features": {c: {k: round(float(v), 4) for k, v in df[c].describe(percentiles=[.5]).items() if k != "count"}
                          for c in ["bytes_sent", "bytes_received", "duration", "packet_rate",
                                    "baseline_deviation", "connection_frequency"]},
    }
    gp = df["generated_prediction"].to_numpy()
    summ["construction_score"] = {
        "accuracy_full": round(float((gp == y).mean()), 5),
        "accuracy_oversight_subset": round(float((ov["generated_prediction"] == ov["is_attack"]).mean()), 5),
        "note": "Observed property of the generated construction score; not a trained-model result.",
    }
    ovy = ov["is_attack"].astype(int).to_numpy()
    pdec = ov["profile_decision"].astype(int).to_numpy()
    pcorr = pdec == ovy
    mcorr = ov["generated_prediction"].to_numpy() == ovy
    dis = pdec != ov["generated_prediction"].to_numpy()
    prof = {}
    for p, g in ov.groupby("oversight_profile"):
        gc = g["profile_decision"].astype(int).to_numpy() == g["is_attack"].astype(int).to_numpy()
        gd = g["profile_decision"].astype(int).to_numpy() != g["generated_prediction"].to_numpy()
        gy = g["is_attack"].astype(int).to_numpy()
        gdec = g["profile_decision"].astype(int).to_numpy()
        bal = 0.5 * ((gdec[gy == 1] == 1).mean() + (gdec[gy == 0] == 0).mean()) if 0 < gy.sum() < gy.size else None
        prof[p] = {"count": len(g), "percent": round(100 * len(g) / len(ov), 3),
                   "observed_accuracy": round(float(gc.mean()), 4),
                   "observed_balanced_accuracy": round(float(bal), 4) if bal is not None else None,
                   "alarm_rate": round(float(gdec.mean()), 4),
                   "model_profile_agreement": round(float(1 - gd.mean()), 4),
                   "confidence_mean": round(float(g["profile_confidence"].mean()), 4),
                   "confidence_median": round(float(g["profile_confidence"].median()), 4),
                   "confidence_min_max": [round(float(g["profile_confidence"].min()), 4),
                                          round(float(g["profile_confidence"].max()), 4)],
                   "ece_10bin": round(_ece(g["profile_confidence"].to_numpy(), gc.astype(float)), 4),
                   "latency_mean_s": round(float(g["generated_decision_latency"].mean()), 3),
                   "latency_median_s": round(float(g["generated_decision_latency"].median()), 3),
                   "latency_sd_s": round(float(g["generated_decision_latency"].std()), 3),
                   "disagreement_rate": round(float(gd.mean()), 4),
                   "profile_correct_within_disagreements": round(float(gc[gd].mean()), 4) if gd.any() else None}
    summ["oversight_subset"] = {
        "label": "Properties of configured/generated oversight profiles - NOT measurements of real security analysts.",
        "majority_class_baseline_accuracy": round(float(max(ovy.mean(), 1 - ovy.mean())), 4),
        "selected_count": len(ov), "selected_percent": round(100 * len(ov) / len(df), 4),
        "selection_rule": "deterministic Top-K by ambiguity_score desc, tie-break flow order",
        "ambiguity": {"min": round(float(ov["ambiguity_score"].min()), 6), "max": round(float(ov["ambiguity_score"].max()), 6),
                      "mean": round(float(ov["ambiguity_score"].mean()), 6), "median": round(float(ov["ambiguity_score"].median()), 6)},
        "class_distribution": pct_table(ov["is_attack"].map({True: "attack", False: "benign"})),
        "profiles": prof,
        "overall_profile_accuracy": round(float(pcorr.mean()), 4),
        "model_profile_agreement": round(float((~dis).mean()), 4),
        "disagreements": {"count": int(dis.sum()),
                          "model_correct": int((dis & mcorr).sum()),
                          "profile_correct": int((dis & pcorr).sum()),
                          "model_benign_profile_attack": int((dis & (pdec == 1)).sum()),
                          "model_attack_profile_benign": int((dis & (pdec == 0)).sum()),
                          "by_attack_type_percent": {k: round(100 * v, 2) for k, v in
                                                     ov.loc[dis, "attack_type"].value_counts(normalize=True).items()}},
        "profile_confidence_disagreement_auc": round(_auc(-ov["profile_confidence"].to_numpy(), dis.astype(int)), 4),
        "latency_overall_mean_sd_s": [round(float(ov["generated_decision_latency"].mean()), 3),
                                      round(float(ov["generated_decision_latency"].std()), 3)],
        "descriptive_policies": {
            "profile_override_on_disagreement": {
                "name": "Profile-override-on-disagreement policy",
                "accuracy": round(float(np.where(dis, pcorr, mcorr).mean()), 4),
                "note": ("Simple descriptive benchmark policy: the generated prediction is replaced by the "
                         "profile decision whenever they disagree. Not an oracle and not optimal; deferral "
                         "policies must be evaluated with probabilities from independently trained models."),
            }
        },
    }
    # shortcut audit: single-feature separability of Track-1 features
    audit = {}
    for c in feature_policy(df)["track1_context_enriched"]:
        s = df[c]
        if pd.api.types.is_bool_dtype(s) or pd.api.types.is_numeric_dtype(s):
            a = _auc(s.astype(float).to_numpy(), y.astype(int))
            audit[c] = {"single_feature_auc": round(max(a, 1 - a), 4)}
        else:
            ct = pd.crosstab(s, df["is_attack"], normalize="index")
            pure = ct.max(axis=1) >= 0.99
            audit[c] = {"rows_in_near_pure_categories_percent":
                        round(100 * s.isin(ct.index[pure]).mean(), 3)}
    summ["shortcut_audit"] = {"features": audit,
                              "flag_rule": "single_feature_auc >= 0.95 or >= 50% rows in near-pure categories",
                              "flagged": [k for k, v in audit.items()
                                          if v.get("single_feature_auc", 0) >= 0.95
                                          or v.get("rows_in_near_pure_categories_percent", 0) >= 50]}
    return summ


def _wasserstein(a: pd.Series, b: pd.Series) -> float:
    qs = np.linspace(0, 1, 1001)
    return round(float(np.mean(np.abs(np.quantile(a, qs) - np.quantile(b, qs)))), 5)


