# 15. VALIDATION
# =============================================================================
def validate_release(df: pd.DataFrame, gen: HITLIoTGeneratorV11,
                     splits: pd.DataFrame | None = None) -> list[tuple[str, bool, str]]:
    """Pre-export validation. Every check is critical: any FAIL blocks the release."""
    cfg = gen.cfg
    n, nb, na = gen.counts()
    k = int(math.floor(cfg["oversight_rate"] * n))
    ov = df["oversight_selected"].to_numpy()
    R: list[tuple[str, bool, str]] = []

    def chk(name, cond, detail=""):
        R.append((name, bool(cond), detail))

    # ---- core benchmark ----
    chk("row count", len(df) == n, f"{len(df)} vs {n}")
    chk("class counts", (df.is_attack.sum() == na) and ((~df.is_attack).sum() == nb),
        f"attack={df.is_attack.sum()} benign={(~df.is_attack).sum()}")
    chk("unique flow_id", df.flow_id.is_unique)
    chk("five device types", set(df.device_type) == set(gen.device_names), str(sorted(set(df.device_type))))
    chk("no Mixed/Unknown/Other device", not set(df.device_type) & {"Mixed", "Unknown", "Other", "mixed", "unknown"})
    chk("one-hot devices complete", (df[[f"device_{d}" for d in gen.device_names]].sum(axis=1) == 1).all())
    chk("twelve attack types + normal", set(df.attack_type) == set(gen.attack_names) | {"normal"})
    chk("attack category counts sum", df.loc[df.is_attack, "attack_type"].value_counts().sum() == na)
    # ---- oversight ----
    chk("oversight count == floor(N*rate)", ov.sum() == k, f"{ov.sum()} vs {k}")
    amb = df["ambiguity_score"].to_numpy()
    chk("Top-K property", amb[~ov].max() <= amb[ov].min(), f"max unselected={amb[~ov].max():.6f} min selected={amb[ov].min():.6f}")
    chk("ambiguity in [0,1]", (amb >= 0).all() and (amb <= 1).all())
    chk("score in [0,1]", df.generated_attack_score.between(0, 1).all())
    sel = df[ov]; uns = df[~ov]
    meta = ["oversight_profile", "profile_decision", "profile_confidence", "generated_decision_latency",
            "model_profile_agreement", "profile_rationale"]
    chk("selected rows have complete metadata", sel[meta].notna().all().all())
    chk("non-selected rows have null metadata", uns[meta].isna().all().all())
    chk("rationale non-empty", (sel.profile_rationale.str.len() > 0).all())
    chk("confidence in [0,1]", sel.profile_confidence.between(0, 1).all())
    chk("latency > 0", (sel.generated_decision_latency > 0).all())
    acc = {p: float((g.profile_decision.astype(int) == g.is_attack.astype(int)).mean())
           for p, g in sel.groupby("oversight_profile")}
    order = cfg["profile_acceptance"]["order"]
    accs = [acc.get(p, float("nan")) for p in order]
    chk("profile performance ordering: high > medium > low", all(a > b for a, b in zip(accs, accs[1:])),
        " > ".join(f"{p}={acc.get(p, float('nan')):.4f}" for p in order))
    lo_min = cfg["profile_acceptance"]["low_competence_min_accuracy"]
    chk(f"low-competence profile accuracy > {lo_min:.2f}", acc.get(order[-1], 0) > lo_min,
        f"{acc.get(order[-1], float('nan')):.4f}")
    # ---- flow integrity ----
    chk("durations > 0", (df.duration > 0).all())
    chk("byte counts >= 0", (df.bytes_sent >= 0).all() and (df.bytes_received >= 0).all())
    chk("packet_count >= 1", (df.packet_count >= 1).all())
    chk("ports in range", df.dst_port.between(1, 65535).all() and df.src_port.between(1, 65535).all())
    chk("no constant dst_mac leakage", df.groupby("is_attack")["dst_mac"].nunique().eq(1).all()
        and df.dst_mac.nunique() == 1)
    # ---- historical features: independent recomputation for one instance ----
    inst = sorted(df.device_name.unique())[0]
    g = df[df.device_name == inst]
    b = g.bytes_sent.to_numpy(); m5 = g.bytes_sent_mean_5.to_numpy()
    mu = gen.baselines[g.device_type.iloc[0]]["bytes_sent"][0]
    ref = np.array([mu] + [b[max(0, i - 5):i].mean() for i in range(1, len(b))])
    chk("historical features prior-only (independent recomputation)", np.allclose(ref, m5), inst)
    chk("chronological row order", (df.timestamp.to_numpy()[1:] >= df.timestamp.to_numpy()[:-1]).all())
    # ---- feature policy ----
    pol = feature_policy(df)
    forbidden = {c for c in df.columns if SCHEMA[c][1] in (L, B, O, S)}
    chk("primary Track-1 flow-only defined", len(pol["track1_primary_flow_only"]) > 0
        and "dst_category" not in pol["track1_primary_flow_only"])
    chk("contextual Track-1 defined", "dst_category" in pol["track1_context_enriched"])
    chk("Track-2 oversight defined", len(pol["track2_oversight"]) > 0)
    chk("Track-1 excludes labels/construction/oversight/identifiers",
        not ((set(pol["track1_primary_flow_only"]) | set(pol["track1_context_enriched"])) & forbidden))
    chk("every column documented", all(c in SCHEMA for c in df.columns))
    chk("device percentages sum to 100", abs(df.device_type.value_counts(normalize=True).sum() - 1) < 1e-9)
    # ---- splits ----
    if splits is not None:
        tol = cfg["splits"]["tolerance"]
        target = {p: cfg["splits"][p] for p in ("train", "validation", "test")}
        chk("split file covers every flow exactly once",
            len(splits) == n and splits.flow_id.is_unique and set(splits.flow_id) == set(df.flow_id))
        for col, lbl in (("temporal_split", "temporal"), ("iid_split", "IID")):
            chk(f"{lbl} split coverage", splits[col].isin(target).all() and splits[col].notna().all())
            prop = splits[col].value_counts(normalize=True)
            chk(f"{lbl} split approximately 70/15/15",
                all(abs(prop.get(p, 0) - t) <= tol for p, t in target.items()),
                ", ".join(f"{p}={prop.get(p, 0):.4f}" for p in target))
        ts = {p: splits.loc[splits.temporal_split == p, "timestamp"] for p in target}
        chk("temporal train precedes validation (strict)", ts["train"].max() < ts["validation"].min(),
            f"{ts['train'].max()} < {ts['validation'].min()}")
        chk("temporal validation precedes test (strict)", ts["validation"].max() < ts["test"].min(),
            f"{ts['validation'].max()} < {ts['test'].min()}")
        chk("no temporal-train record later than any test record", ts["train"].max() < ts["test"].min())
    return R


# =============================================================================
# 18-19. EXPORT
# =============================================================================
SOURCE_NAME = "hitl_iot_generator_v1_1.py"


def resolve_source(source_file: Path | None) -> Path | None:
    """Locate the generator source: explicit --source-file, else __file__ (script or imported module)."""
    if source_file is not None:
        return source_file.resolve() if source_file.is_file() else None
    f = globals().get("__file__")
    if f and Path(f).is_file():
        return Path(f).resolve()
    return None


def write_release(df: pd.DataFrame, gen: HITLIoTGeneratorV11, out: Path, results,
                  splits: pd.DataFrame, source: Path | None) -> dict[str, str]:
    """Write all artefacts. No volatile values (e.g. wall-clock time) are written into any file,
    so every artefact - including the manifest - is byte-for-byte reproducible."""
    cfg = gen.cfg
    out.mkdir(parents=True, exist_ok=True)
    v = cfg["version"]
    name = cfg["dataset_name"]
    ff = cfg["csv_float_format"]
    files: dict[str, Path] = {}

    if source is not None:
        files["generator"] = out / SOURCE_NAME
        if source != files["generator"].resolve():
            shutil.copy2(source, files["generator"])  # verbatim copy, source unchanged

    files["dataset"] = out / f"{name}_dataset_v{v}.csv"
    df.to_csv(files["dataset"], index=False, float_format=ff, lineterminator="\n")
    files["oversight"] = out / f"{name}_oversight_subset_v{v}.csv"
    df[df.oversight_selected].to_csv(files["oversight"], index=False, float_format=ff, lineterminator="\n")

    cfg_out = copy.deepcopy(cfg)
    cfg_out["derived"] = {
        "normalized_attack_proportions": gen.attack_proportions,
        "ambiguity_definition": "a_i = 1 - 2|generated_attack_score_i - 0.5|",
        "top_k_rule": "K = floor(oversight_rate * N); sort ambiguity desc, flow order asc; select first K",
        "latency_formula": "t_i = U(t_min_k, t_max_k) * (1 + ambiguity_coefficient * a_i)",
        "profile_decision_rule": ("P = w_anchor*E_implied + (1-w_anchor)*((1-w_ctx)*flow_evidence + w_ctx*context_evidence); "
                                  "E_implied = offset + logit(generated_attack_score)/slope; "
                                  "decision = 1[P + N(0, noise_sd) > threshold]"),
        "profile_confidence_rule": ("c = c_min + (c_max-c_min)*tanh(|margin|/margin_scale)*(1-ambiguity_penalty*a) "
                                    "+ N(0, noise_sd); clipped to [0,1]; no ground truth, no model agreement"),
        "construction_score_rule": "sigmoid(slope*(flow_evidence - offset) + N(0, logit_noise_sd))",
        "temporal_split_rule": ("sort by (timestamp, flow_id); earliest 70% train, next 15% validation, latest 15% test; "
                                "cut points advanced to next timestamp change for strict boundaries"),
        "iid_split_rule": "stratified by attack_type, seeded shuffle, 70/15/15",
        "service_map": {str(k): v for k, v in SERVICE_MAP.items()},
    }
    files["config"] = out / f"{name}_config_v{v}.json"
    files["config"].write_text(json.dumps(cfg_out, indent=2))

    sch = schema_frame(df)
    files["schema_csv"] = out / f"{name}_schema_v{v}.csv"
    sch.to_csv(files["schema_csv"], index=False, lineterminator="\n")
    files["schema_json"] = out / f"{name}_schema_v{v}.json"
    files["schema_json"].write_text(sch.to_json(orient="records", indent=2))
    pol = feature_policy(df)
    files["policy"] = out / f"{name}_feature_policy_v{v}.json"
    files["policy"].write_text(json.dumps(pol, indent=2))
    files["splits"] = out / f"{name}_splits_v{v}.csv"
    splits.to_csv(files["splits"], index=False, lineterminator="\n")

    summ = summarise(df, gen)
    summ["splits"] = split_summary(df, splits)
    summ["validation"] = [{"check": c, "passed": p, "detail": d} for c, p, d in results]
    files["summary"] = out / f"{name}_summary_v{v}.json"
    files["summary"].write_text(json.dumps(summ, indent=2, default=str))
    files["report"] = out / f"{name}_generation_report_v{v}.md"
    files["report"].write_text(render_report(summ))
    files["changelog"] = out / f"CHANGELOG_v{v}.md"
    files["changelog"].write_text(CHANGELOG)
    files["mapping"] = out / f"{name}_schema_mapping_v1.0_to_v{v}.csv"
    pd.DataFrame(SCHEMA_MAPPING, columns=["v1.0 field", f"v{v} field", "action", "reason"]).to_csv(
        files["mapping"], index=False, lineterminator="\n")

    hashes = {p.name: sha256_of(p) for p in files.values()}
    sp = summ["splits"]
    manifest = {
        "dataset_name": name, "version": v, "generator_version": GENERATOR_VERSION,
        "seed": cfg["seed"], "rows": len(df), "columns": df.shape[1],
        "class_counts": {"benign": int((~df.is_attack).sum()), "attack": int(df.is_attack.sum())},
        "device_counts": {k: int(v2) for k, v2 in df.device_type.value_counts().items()},
        "attack_counts": {k: int(v2) for k, v2 in df.loc[df.is_attack, "attack_type"].value_counts().items()},
        "oversight_count": int(df.oversight_selected.sum()),
        "evaluation_protocols": {
            "primary_evaluation_split": "temporal",
            "secondary_evaluation_split": "iid_stratified",
            "proportions": {p: cfg["splits"][p] for p in ("train", "validation", "test")},
            "iid_seed": cfg["seed"], "iid_stratify_by": cfg["splits"]["stratify_by"],
            "temporal": sp["temporal"], "iid_stratified": sp["iid_stratified"],
        },
        "feature_policies": {"track1_primary": "track1_primary_flow_only",
                             "track1_secondary": "track1_context_enriched",
                             "track2": "track2_oversight",
                             "n_features": {k: len(pol[k]) for k in
                                            ("track1_primary_flow_only", "track1_context_enriched", "track2_oversight")}},
        "generator": {"filename": SOURCE_NAME if source is not None else None,
                      "sha256": hashes.get(SOURCE_NAME), "version": GENERATOR_VERSION},
        "execution_configuration": {"score_mode": cfg["score_mode"], "legacy_profile_mode": cfg["legacy_profile_mode"],
                                    "config_file": files["config"].name},
        "publication_ready": source is not None and all(p for _, p, _ in results),
        "files": {k: p.name for k, p in files.items()},
        "sha256": hashes,
        "environment": {"python": sys.version.split()[0], "platform": platform.platform(),
                        "numpy": np.__version__, "pandas": pd.__version__},
        "hash_coverage": ("sha256 covers every file listed in 'files'. The manifest is hashed in the checksum "
                          "file; the checksum file is not hashed (no self-hashing)."),
        "reproducibility_note": ("No wall-clock timestamps are stored; identical code, config, seed and "
                                 "numpy/pandas versions reproduce identical files."),
        "scope_note": "All values are generated. No real traffic, analysts, or compliance assessment are represented.",
    }
    mpath = out / f"{name}_manifest_v{v}.json"
    mpath.write_text(json.dumps(manifest, indent=2))
    hashes[mpath.name] = sha256_of(mpath)
    cpath = out / f"{name}_checksums_v{v}.txt"
    cpath.write_text("".join(f"{h}  {fn}\n" for fn, h in hashes.items()))
    return hashes


def verify_release(out: Path, df: pd.DataFrame, cfg: dict, source: Path | None) -> list[tuple[str, bool, str]]:
    """Post-export integrity checks against the files actually on disk."""
    v, name = cfg["version"], cfg["dataset_name"]
    R: list[tuple[str, bool, str]] = []
    gpath = out / SOURCE_NAME
    R.append(("generator source included", source is not None and gpath.is_file(),
              str(gpath) if gpath.is_file() else "missing: run the saved .py script or pass --source-file"))
    lines = (out / f"{name}_checksums_v{v}.txt").read_text().splitlines()
    listed = {ln.split("  ", 1)[1]: ln.split("  ", 1)[0] for ln in lines if ln.strip()}
    R.append(("generator source SHA-256 recorded", SOURCE_NAME in listed, listed.get(SOURCE_NAME, "absent")[:16]))
    bad = [fn for fn, h in listed.items() if not (out / fn).is_file() or sha256_of(out / fn) != h]
    R.append(("all listed artefacts match their SHA-256", not bad, ", ".join(bad)))
    expected = {f"{name}_dataset_v{v}.csv", f"{name}_oversight_subset_v{v}.csv", f"{name}_config_v{v}.json",
                f"{name}_schema_v{v}.csv", f"{name}_schema_v{v}.json", f"{name}_feature_policy_v{v}.json",
                f"{name}_splits_v{v}.csv", f"{name}_summary_v{v}.json", f"{name}_generation_report_v{v}.md",
                f"CHANGELOG_v{v}.md", f"{name}_schema_mapping_v1.0_to_v{v}.csv", f"{name}_manifest_v{v}.json"}
    R.append(("all authoritative artefacts hashed", expected <= set(listed), ", ".join(sorted(expected - set(listed)))))
    man = json.loads((out / f"{name}_manifest_v{v}.json").read_text())
    R.append(("manifest consistent with files",
              all(listed.get(fn) == h for fn, h in man["sha256"].items()) and man["rows"] == len(df)
              and man["oversight_count"] == int(df.oversight_selected.sum()), ""))
    c = json.loads((out / f"{name}_config_v{v}.json").read_text())
    R.append(("config consistent with generated dataset",
              c["total_records"] == len(df) and int(round(c["total_records"] * c["attack_ratio"])) == int(df.is_attack.sum())
              and c["seed"] == cfg["seed"], ""))
    return R


def render_report(s: dict) -> str:
    def tbl(d: dict, head=("Value", "Count", "Percent")) -> str:
        lines = [f"| {head[0]} | {head[1]} | {head[2]} |", "|---|---:|---:|"]
        lines += [f"| {k} | {v['count']:,} | {v['percent']:.3f}% |" for k, v in d.items()]
        return "\n".join(lines)
    ds, ov = s["dataset"], s["oversight_subset"]
    out = [f"# {ds['name']} v{ds['version']} generation report",
           "", "All values below are computed automatically from the saved dataframe. "
           "All data are generated; no value is a real-traffic or real-analyst measurement.", "",
           f"Seed {ds['seed']} | rows {ds['rows']:,} | columns {ds['columns']} | "
           f"{ds['first_timestamp']} to {ds['last_timestamp']} | score_mode={ds['score_mode']} | "
           f"legacy_profile_mode={ds['legacy_profile_mode']}", "",
           "## Class distribution", tbl(s["class_distribution"]), "",
           "## Device distribution", tbl(s["device_distribution"]), "",
           "## Attack distribution (observed)", tbl(s["attack_distribution_observed"]), "",
           "## Protocol distribution", tbl(s["protocol_distribution"]), "",
           "## Destination category (benign)", tbl(s["destination_category"]["benign"]), "",
           "## Destination category (attack)", tbl(s["destination_category"]["attack"]), "",
           "## Port mimicry",
           f"Configured range: {s['port_mimicry']['configured_range_percent'][0]}%–"
           f"{s['port_mimicry']['configured_range_percent'][1]}%. Observed share of attacks on a "
           f"device-expected port: {s['port_mimicry']['observed_attack_rate_device_expected_port_percent']}%.", "",
           "## Byte volume",
           f"Median bytes_sent benign {s['byte_volume']['benign_median']:,.0f} / attack "
           f"{s['byte_volume']['attack_median']:,.0f}; median ratio {s['byte_volume']['median_byte_volume_ratio']}; "
           f"Wasserstein(log10 bytes) {s['byte_volume']['wasserstein_log10_bytes']}.", "",
           "## Construction score",
           f"Accuracy of generated_prediction: full {s['construction_score']['accuracy_full']}, "
           f"oversight subset {s['construction_score']['accuracy_oversight_subset']}.", "",
           "## Evaluation splits",
           "Temporal = PRIMARY (chronological, leakage-conservative). IID stratified = SECONDARY.", "",
           "| Protocol | Part | n | Proportion | Attack rate | First timestamp | Last timestamp |",
           "|---|---|---:|---:|---:|---|---|"]
    for proto, parts in s["splits"].items():
        for part, v in parts.items():
            out.append(f"| {proto} | {part} | {v['count']:,} | {v['proportion']} | {v['attack_rate']} | "
                       f"{v['first_timestamp']} | {v['last_timestamp']} |")
    out += ["", "## Configured/generated oversight profiles",
            "Properties of configured/generated oversight profiles — not measurements of real security analysts.", "",
            f"Selected {ov['selected_count']:,} ({ov['selected_percent']}%). Ambiguity range "
            f"[{ov['ambiguity']['min']}, {ov['ambiguity']['max']}]. Model–profile agreement "
            f"{ov['model_profile_agreement']}. Overall profile accuracy {ov['overall_profile_accuracy']}. "
            f"Majority-class baseline on the subset {ov['majority_class_baseline_accuracy']}.", "",
            "| Profile | n | % | Accuracy | Balanced acc. | Alarm rate | Agreement | Conf. mean | Conf. median | ECE | Latency mean (s) | Latency median (s) |",
            "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for p, v in ov["profiles"].items():
        out.append(f"| {p} | {v['count']:,} | {v['percent']} | {v['observed_accuracy']} | "
                   f"{v['observed_balanced_accuracy']} | {v['alarm_rate']} | {v['model_profile_agreement']} | "
                   f"{v['confidence_mean']} | {v['confidence_median']} | {v['ece_10bin']} | "
                   f"{v['latency_mean_s']} | {v['latency_median_s']} |")
    d = ov["disagreements"]
    out += ["", f"Disagreements: {d['count']:,} (generated prediction correct {d['model_correct']:,}, profile correct "
                f"{d['profile_correct']:,}; prediction-benign/profile-attack {d['model_benign_profile_attack']:,}, "
                f"prediction-attack/profile-benign {d['model_attack_profile_benign']:,}). "
                f"AUC of low profile confidence for predicting disagreement: {ov['profile_confidence_disagreement_auc']}.",
            "", "## Shortcut audit (Track-1 context-enriched features)",
            f"Rule: {s['shortcut_audit']['flag_rule']}. Flagged: {s['shortcut_audit']['flagged'] or 'none'}.", "",
            "| Feature | Single-feature AUC / near-pure rows % |", "|---|---:|"]
    for k, v in s["shortcut_audit"]["features"].items():
        out.append(f"| {k} | {list(v.values())[0]} |")
    out += ["", "## Pre-export validation", "| Check | Result | Detail |", "|---|---|---|"]
    out += [f"| {r['check']} | {'PASS' if r['passed'] else 'FAIL'} | {r['detail']} |" for r in s["validation"]]
    return "\n".join(out) + "\n"


CHANGELOG = """# HITL-IoT v1.1 changelog

v1.0 is preserved unchanged. v1.1 is a new version; hashes and numerical results differ from v1.0
by design. Every v1.1 statistic must be taken from the v1.1 summary/report, not from v1.0 text.

## Configuration and counts
- attack_ratio is now functional: attack = round(N*ratio), benign = N - attack (v1.0 hard-coded counts).
- Attack-category weights explicitly normalised; integer counts by largest remainder; seeded shuffle.
- Device allocation explicit (uniform 0.20 default) by largest remainder within each class.
- One named, seeded NumPy stream per component (no unseeded or mixed RNG calls).

## Taxonomy / encoding
- One-hot columns now exist for all five devices (v1.0 lacked device_tv and device_doorbell,
  which produced the legacy "Mixed/Unknown" artefact).
- Stable flow_id added.

## Shortcut / leakage removal
- dst_mac: v1.0 set FF:FF:FF:FF:FF:FF for every attack only (perfect label leak). v1.1 uses the
  gateway MAC for all external flows.
- Protocol: v1.0 forced all attacks to TCP (any UDP flow was benign). v1.1 derives transport from
  port rules for both classes (DNS/NTP/CoAP/SSDP/SNMP/mDNS UDP; QUIC-like UDP/443).
- Duration: v1.0 benign <=10 s vs attacks up to 60 s. v1.1 uses device-specific benign ranges and
  attack-specific ranges, with benign-like draws at probability data_similarity.
- Benign DNS/NTP auxiliary flows added so a non-device port is not an automatic attack indicator.
- risk_score (label-conditioned, non-overlapping ranges) removed from canonical output; available only
  as configured_intrinsic_risk in score_mode=legacy_risk.
- is_internal_dst and is_localhost removed (constant False in v1.0).

## Construction score and oversight
- ml_confidence -> generated_attack_score, computed from observable flow evidence plus logit noise
  (v1.0: label-conditioned risk + U(-0.15,0.15)). ml_prediction -> generated_prediction
  (threshold 0.5 on the logistic score; v1.0 used 0.6).
- ambiguity_score retained in all files.
- Oversight selection: deterministic Top-K by ambiguity (v1.0: threshold >0.4 then weighted random
  sampling, contradicting the manuscript).
- Profile decisions generated from evidence + profile-specific context weight, model anchoring,
  threshold and noise (v1.0: copy/flip ground truth with fixed accuracy). Accuracy is now an observed
  output. v1.0 behaviour available as legacy_profile_mode=true for comparison only.
- Profile confidence from decision margin and ambiguity; no longer depends on agreement with the
  model (v1.0 leak: confidence predicted disagreement with AUC ~0.95).
- profile_rationale added (template-generated; not analyst reasoning).
- Non-selected rows carry nulls instead of 0/-1 placeholders.
- Human-oriented names replaced (see schema mapping); file renamed to oversight_subset.

## Feature semantics
- packet_rate = packet_count / duration (v1.0: packet_size / duration, wrong units); packet_count added.
- baseline_deviation computed as |bytes_sent - mu_d| / sigma_d from configured benign device ranges
  (v1.0: random U(-2,2)); duration_deviation and packet_size_deviation added.
- connection_frequency = prior flows of the same instance in the preceding 60 s (v1.0: random 1-10;
  connections_per_hour config was unused and is removed).
- Rolling statistics per device instance over previous flows only (v1.0: per device type, including
  the current flow).
- Destination addresses use RFC 5737 documentation blocks; categories replace live-IP reputation claims.
- service_category added (port-derived; not application-protocol emulation).

## Reporting
- "Realism" wording removed; "byte volume overlap ratio" renamed median_byte_volume_ratio and
  complemented by IQRs and a Wasserstein distance.
- Automatic summary, report, shortcut audit, schema, feature policy, fixed splits, manifest, and
  expanded checksums.

## Final v1.1 revision (freeze candidate)
- Profile anchoring corrected: anchored profiles now use the evidence-scale value implied by the
  construction score (offset + logit(score)/slope) instead of the raw score. The draft added a
  0.5-centred score to evidence thresholded at 0.35, biasing all anchored profiles towards "attack"
  (low-competence alarm rate 0.69 on an ~83%-benign queue). This affects all three profiles.
- Low-competence profile: threshold 0.30 -> 0.35 (common threshold for all profiles; profiles now
  differ only in context access, anchoring and noise). Accuracy is not hard-coded; it is an observed
  output checked by acceptance rules (ordering high > medium > low; low > 0.50).
- Added chronological temporal split (PRIMARY) with strict timestamp boundaries; the stratified IID
  split is retained as SECONDARY. Split file: flow_id, timestamp, temporal_split, iid_split.
- Feature policy: track1_primary_flow_only (PRIMARY IDS set, excludes dst_category),
  track1_context_enriched (SECONDARY), track2_oversight.
- "Oracle" terminology removed. The disagreement-override figure is reported only in the summary JSON
  as the descriptive "Profile-override-on-disagreement policy".
- Generator source copied verbatim (shutil.copy2) and hashed automatically; --source-file option for
  interactive use; release is not marked publication-ready without the source.
- Manifest contains no wall-clock timestamp, so every artefact is byte-reproducible; the manifest is
  hashed in the checksum file (no self-hashing).
- --check-determinism now regenerates the full release in a temporary directory and compares SHA-256
  of every artefact.
- Added validations: profile ordering, low-profile accuracy, split coverage/proportions/strict
  chronology, independent recomputation of a prior-only rolling feature, source inclusion/hash,
  checksum/manifest/config consistency.
"""

