def run_pipeline(cfg: dict, out: Path, source: Path | None, verbose: bool = True):
    """Generate, validate, export and verify. Returns (df, splits, pre_results, post_results, hashes)."""
    gen = HITLIoTGeneratorV11(cfg)
    df = gen.generate(verbose=verbose)
    splits = make_splits(df, cfg)
    pre = validate_release(df, gen, splits)
    if not all(p for _, p, _ in pre):
        return df, splits, pre, [], {}
    hashes = write_release(df, gen, out, pre, splits, source)
    post = verify_release(out, df, cfg, source)
    return df, splits, pre, post, hashes


def _print_checks(title: str, results) -> None:
    print(f"\n{title}")
    for c, p, d in results:
        print(f"  [{'PASS' if p else 'FAIL'}] {c}{'  (' + d + ')' if d else ''}")


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="HITL-IoT v1.1 generator")
    ap.add_argument("--config", type=Path, help="JSON config (defaults used if omitted)")
    ap.add_argument("--out", type=Path, default=Path("release_v1.1"))
    ap.add_argument("--write-config", type=Path, help="write default config to this path and exit")
    ap.add_argument("--check-determinism", action="store_true",
                    help="regenerate the full release in a temp directory and compare all SHA-256 values")
    ap.add_argument("--source-file", type=Path, help="path to this generator's .py (interactive use)")
    # parse_known_args ignores arguments injected by Jupyter/IPython (e.g. "-f kernel.json")
    args, _unknown = ap.parse_known_args(argv)

    if args.write_config:
        args.write_config.write_text(json.dumps(DEFAULT_CONFIG, indent=2))
        print(f"Default config written to {args.write_config}")
        return 0
    cfg = copy.deepcopy(DEFAULT_CONFIG)
    if args.config:
        user = json.loads(args.config.read_text())
        user.pop("derived", None)
        cfg.update(user)
    source = resolve_source(args.source_file)

    print("=" * 78)
    print(f"{cfg['dataset_name']} GENERATOR v{cfg['version']}  |  CONTROLLED BENCHMARK CONSTRUCTION")
    print("=" * 78)
    if source is None:
        print("WARNING: generator source not found (interactive paste?). The release will NOT be "
              "publication-ready. Run `python hitl_iot_generator_v1_1.py --out release_v1.1` "
              "or pass --source-file.")
    df, splits, pre, post, hashes = run_pipeline(cfg, args.out, source)
    _print_checks("PRE-EXPORT VALIDATION", pre)
    if not all(p for _, p, _ in pre):
        print("\nCritical validation failure: release NOT written.")
        return 1
    _print_checks("RELEASE INTEGRITY", post)

    det_ok = True
    if args.check_determinism:
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            _, _, pre2, _, h2 = run_pipeline(copy.deepcopy(cfg), Path(tmp), source, verbose=False)
            names = {"dataset": f"{cfg['dataset_name']}_dataset_v{cfg['version']}.csv",
                     "oversight-subset": f"{cfg['dataset_name']}_oversight_subset_v{cfg['version']}.csv",
                     "split": f"{cfg['dataset_name']}_splits_v{cfg['version']}.csv",
                     "summary": f"{cfg['dataset_name']}_summary_v{cfg['version']}.json"}
            det = [(f"deterministic {k} hash", hashes.get(fn) == h2.get(fn), "") for k, fn in names.items()]
            others = [fn for fn in hashes if fn not in names.values()]
            diff = [fn for fn in others if hashes[fn] != h2.get(fn)]
            det.append(("deterministic hashes for all other artefacts", not diff, ", ".join(diff)))
        _print_checks("DETERMINISM (full regeneration in a temporary directory)", det)
        det_ok = all(p for _, p, _ in det)

    s = json.loads((args.out / f"{cfg['dataset_name']}_summary_v{cfg['version']}.json").read_text())
    n = len(df); na = int(df.is_attack.sum())
    print("\nDATASET")
    print(f"  records={n:,}  benign={n - na:,}  attack={na:,}  attack_rate={na / n:.4f}")
    print("  devices: " + ", ".join(f"{k}={v:,}" for k, v in df.device_type.value_counts().items()))
    print("  attacks: " + ", ".join(f"{k}={v:,}" for k, v in df.loc[df.is_attack, 'attack_type'].value_counts().items()))
    ov = s["oversight_subset"]
    print(f"\nCONFIGURED/GENERATED OVERSIGHT PROFILES (not real analysts)")
    print(f"  selected={ov['selected_count']:,} ({ov['selected_percent']}%)  "
          f"majority-class baseline={ov['majority_class_baseline_accuracy']}  "
          f"model-profile agreement={ov['model_profile_agreement']}")
    for p, v in ov["profiles"].items():
        print(f"  {p:18s} n={v['count']:5,} ({v['percent']:6.3f}%)  acc={v['observed_accuracy']:.4f}  "
              f"bal_acc={v['observed_balanced_accuracy']:.4f}  conf mean/median={v['confidence_mean']:.3f}/"
              f"{v['confidence_median']:.3f}  latency mean/median={v['latency_mean_s']:.2f}/{v['latency_median_s']:.2f}s  "
              f"agreement={v['model_profile_agreement']:.4f}")
    print("\nSPLITS")
    for proto, parts in s["splits"].items():
        print(f"  {proto}:")
        for part, v in parts.items():
            print(f"    {part:10s} n={v['count']:7,} ({v['proportion']:.4f})  attack_rate={v['attack_rate']:.4f}  "
                  f"{v['first_timestamp']} -> {v['last_timestamp']}")
    print(f"\nRELEASE: {args.out.resolve()}")
    for fn, h in hashes.items():
        print(f"  {h}  {fn}")
    ok = all(p for _, p, _ in post) and det_ok
    print(f"\nPUBLICATION-READY: {'YES' if ok else 'NO'}")
    return 0 if ok else 1


def _in_notebook() -> bool:
    try:
        from IPython import get_ipython  # type: ignore
        return get_ipython() is not None
    except ImportError:
        return False


if __name__ == "__main__":
    if _in_notebook():
        main([])            # notebook: run with defaults, no SystemExit
    else:
        sys.exit(main())
